import {initAlbumView} from './album-view.mjs';
import {supabase} from './auth-client.mjs';import {playerParameters,playerLink} from './player-model.mjs';
const $=id=>document.getElementById(id),root=new URL('./album-data/',import.meta.url),el=(t,s,c)=>{const n=document.createElement(t);if(s!==undefined)n.textContent=s;if(c)n.className=c;return n;};let data,player,selected=1;const inventory=new Map();
function render(){const total=data.cards.filter(c=>(inventory.get(c.number)||0)>0).length,gold=data.cards.filter(c=>c.gold&&(inventory.get(c.number)||0)>0).length;$('album-progress').textContent=total+' / 135';$('gold-progress').textContent=gold+' / 17';$('album-set-strip').replaceChildren(...data.sets.map(set=>{const b=el('button',undefined,'set-choice');b.type='button';b.setAttribute('aria-label',set.name);b.setAttribute('aria-pressed',String(set.number===selected));const image=el('img');image.src=new URL(set.image,root);image.alt=set.name;b.append(image,el('span',set.name),el('small',String(set.cards.filter(n=>(inventory.get(n)||0)>0).length),'set-count'));b.onclick=()=>{selected=set.number;render();};return b;}));$('album-sets').replaceChildren(...data.cards.filter(c=>c.set===selected).map(card=>{const q=inventory.get(card.number)||0,tile=el('article',undefined,'album-card'+(q?' collected':'')),frame=el('div',undefined,'card-picture'),art=el('img'),stars=el('img');art.src=new URL(card.image,root);art.alt=card.name;art.loading='lazy';art.className='card-art';stars.src=new URL('../tatari-data/stars/'+String(card.stars).padStart(2,'0')+'.png',root);stars.alt=card.stars+' stars';stars.className='album-card-stars';frame.append(art,el('strong',q?'Owned: '+q:'','owned-overlay'),stars);tile.append(frame,el('h3','#'+card.number+(card.gold?'G':'')+' · '+card.name),Object.assign(el('img',undefined,'list-stars'),{src:new URL('../tatari-data/stars/'+String(card.stars).padStart(2,'0')+'.png',root).href,alt:card.stars+' stars'}),el('span','Owned: '+q,'list-owned'));return tile;}));}
try{const params=playerParameters(location.href,import.meta.url);if(!Number.isInteger(params.album)||params.album<1||params.album>32767)throw Error('Invalid album.');const {data:result,error}=await supabase.rpc('get_player_album',{p_uid:params.uid,p_album:params.album});if(error)throw Error('Player albums are not available yet.');if(!result)throw Error('This player album is private or was not found.');if(result.season!=='autumn-tales')throw Error('This album is not supported yet.');player=result;const r=await fetch(new URL('autumn-tales.json',root));if(!r.ok)throw Error('Album data could not load.');data=await r.json();for(const item of player.inventory)inventory.set(item.card_number,item.quantity);$('player-name').textContent=player.name;$('player-uid').textContent='In-Game ID: '+player.uid;history.replaceState(null,'',playerLink(player.uid,params.album,import.meta.url));$('album-status').textContent='';render();}catch(error){$('album-status').textContent=error.message;}

initAlbumView();
